from pathlib import Path
import markdown,re,html,hashlib,json
P=Path(__file__).resolve().parent
scenes=[('thursday','THURSDAY.md','Thursday','08-thursday-tea'),('dream','related/DREAM.md','The Last Temptation of Emanuel','06-dream-classroom'),('tara','related/TARA.md','After the Dream','07-tara-listens'),('telephone','related/TEA.md','Tea with a Russian',None)]
css='''*{box-sizing:border-box}body{margin:0;background:#131f27;color:#f0e8db;font:20px/1.85 Georgia,serif;overflow-wrap:anywhere}header,main,footer{max-width:960px;margin:auto;padding:28px}a{color:#9dddcf}h1{font-size:clamp(45px,8vw,76px);line-height:1.1;font-weight:normal;color:#edc98f}h2,h3{color:#edc98f;font-weight:normal}strong{color:#9dddcf}aside,figcaption,nav,footer{font:14px/1.75 system-ui}aside{background:#22343d;border-left:3px solid #d6b580;padding:20px;margin:25px 0}nav{display:flex;flex-wrap:wrap;gap:18px}section{padding:25px 0;border-bottom:1px solid #52636b}figure{margin:30px 0}img{width:100%;height:auto;display:block;border-radius:7px}figcaption{color:#bbc7c5;margin-top:9px}.board-cue{font:14px/1.7 system-ui;color:#c9d9d2;padding:12px 0}p:has(>em:only-child){color:#c6cfca}@media print{body{background:white;color:black}h1,h2,h3,strong,a{color:black}aside,nav{display:none}section{break-before:page}img{max-height:16cm;object-fit:contain}}'''
parts=[]
for sid,file,title,image in scenes:
 raw=(P/file).read_text();body=markdown.markdown(raw,extensions=['extra'])
 out='<section id="'+sid+'"><p class="board-cue">Standing stage direction: a physical board and writing tools remain visible and within reach. Performers may improvise their annotations.</p>'
 if image:out+='<figure><a href="../house-of-returning-authors/art/'+image+'.png"><img src="../house-of-returning-authors/art/'+image+'.png" alt="New fictional stage illustration for '+html.escape(title)+'; a reachable writing board is part of the set." loading="lazy" width="1536" height="1024"></a><figcaption>New AI-generated stage illustration. <a href="../house-of-returning-authors/art/IMAGE-PROMPTS.md">Prompts and credits</a>.</figcaption></figure>'
 if sid=='tara':out+='<h2>After the Dream</h2>'
 parts.append(out+body+'<p><a href="'+file+'">Unchanged source text</a> · <a href="../house-of-returning-authors/#'+('tea-phone' if sid=='telephone' else sid)+'">Read in the megaplay</a></p></section>')
page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Thursday — Manny Glover</title><meta name="description" content="Thursday, published as written, with the dream and tea scenes that lead to it. Part of The House of Returning Authors."><style>'+css+'</style></head><body><header><nav><a href="../house-of-returning-authors/#thursday">The complete megaplay</a><a href="../">HRL Portfolio</a></nav><h1>Thursday</h1><p>Manny Glover — Michael Emanuel Glover<br>Developed in dialogue with ChatGPT / Codex</p><nav><a href="#thursday">Thursday</a><a href="#dream">The dream</a><a href="#tara">Tara</a><a href="#telephone">The telephone call</a><a href="THURSDAY.md">Download Thursday</a></nav></header><main><aside>Fictional theatre. Thursday and the related scenes are preserved as written. The board is a new standing production convention, placed outside their source text. Characters inspired by named people are fictional portrayals; the imagined offices, relationships, and intelligence-service history are not factual claims. <a href="../house-of-returning-authors/STAGING.md">Read the board convention</a>.</aside>'+''.join(parts)+'</main><footer><a href="README.md">Publication notes</a> · <a href="../house-of-returning-authors/">The House of Returning Authors</a></footer></body></html>'
(P/'index.html').write_text(page)
(P/'SOURCE-HASHES.json').write_text(json.dumps({file:hashlib.sha256((P/file).read_bytes()).hexdigest() for _,file,_,_ in scenes},indent=2)+'\n')
print('Built unchanged Thursday and three preceding scenes.')
